def chunk(seq, size):
    if size <= 0:
        raise ValueError("Chunk size must be positive")
    chunks = []
    for i in range(0, len(seq), size):
        chunk = seq[i:i+size]
        if chunk:
            chunks.append(chunk)
    return chunks
